#!/usr/bin/env python3
"""
Nexus report kit: branded test reports for the Nexus platform.

One self-contained file (standard library only). It turns the raw result files
the test runs already write (pytest --json-report, behave JSON, the endurance
summary) into three kinds of static page, all in the Nexus AI product theme:

  report     one detailed report for a test type (unit, integration, bdd, ...)
  site       a component's whole folder: its dashboard plus every report
  portal     the front page that lists every component

Usage:
  python nexus_report_kit.py report --kind unit --input unit.json --output unit.html --component "AI Engine"
  python nexus_report_kit.py site   --reports tests/reports --out dist/ai-engine --component "AI Engine" --slug ai-engine
  python nexus_report_kit.py portal --out dist

Pages are single files: styles, icons and the header image are inlined, so a
report can be opened from disk, attached to an email or printed to PDF.
"""
from __future__ import annotations

import argparse
import html
import json
import os
import sys
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional

KIT_VERSION = "1.0.0"

# ---------------------------------------------------------------- catalogue

#: Test types, in the order they are listed. `icon` is a name in ICONS.
KINDS: Dict[str, Dict[str, str]] = {
    "unit":        {"label": "Unit tests",        "icon": "flask",        "about": "Each function and class checked on its own."},
    "integration": {"label": "Integration tests", "icon": "link",         "about": "Services and APIs working together."},
    "contract":    {"label": "Contract tests",    "icon": "document",     "about": "API requests and responses match the agreed shape."},
    "property":    {"label": "Property tests",    "icon": "shuffle",      "about": "Rules that must hold for any generated input."},
    "e2e":         {"label": "End-to-end tests",  "icon": "route",        "about": "Complete flows through the running system."},
    "journeys":    {"label": "Journey tests",     "icon": "workflow",     "about": "Multi-step business journeys from start to finish."},
    "bdd":         {"label": "BDD scenarios",     "icon": "clipboard",    "about": "Behaviour written as Given / When / Then."},
    "endurance":   {"label": "Endurance tests",   "icon": "heartbeat",    "about": "Stability and speed under sustained load."},
}
#: Components shown on the portal, in order.
COMPONENTS: Dict[str, Dict[str, str]] = {
    "ai-engine": {"label": "AI Engine", "icon": "brain-ai", "about": "Job engine, agents and reasoning runtime."},
    "backend":   {"label": "Backend",   "icon": "server",   "about": "Ontology APIs, control plane and data plane services."},
    "deployer":  {"label": "Deployer",  "icon": "cloud",    "about": "Infrastructure and capability deployment."},
    "simulator": {"label": "Simulator", "icon": "cube",     "about": "Enterprise system simulators and sample data."},
}

