# ------------------------------------------------------------------ helpers

def esc(value: Any) -> str:
    return html.escape("" if value is None else str(value), quote=True)


def icon(name: str, cls: str = "") -> str:
    d = ICONS.get(name) or ICONS["document"]
    return f'<svg class="ico {cls}" viewBox="{d["viewBox"]}" fill="currentColor" aria-hidden="true" focusable="false">{d["body"]}</svg>'


def fmt_duration(seconds: Optional[float]) -> str:
    if seconds is None:
        return "—"
    s = float(seconds)
    if s <= 0:
        return "0 ms"
    if s < 0.001:
        return "< 1 ms"
    if s < 1:
        return f"{s * 1000:.0f} ms"
    if s < 60:
        return f"{s:.2f} s"
    m, sec = divmod(int(round(s)), 60)
    if m < 60:
        return f"{m} min {sec:02d} s"
    h, m = divmod(m, 60)
    return f"{h} h {m:02d} min"


def fmt_when(epoch: Optional[float]) -> str:
    if not epoch:
        return "—"
    return datetime.fromtimestamp(float(epoch), tz=timezone.utc).strftime("%d %b %Y, %H:%M UTC")


def pct(part: float, whole: float) -> float:
    return round(100.0 * part / whole, 1) if whole else 0.0


def fmt_pct(value: float) -> str:
    return f"{value:.0f}%" if float(value).is_integer() else f"{value:.1f}%"


def status_of(summary: Dict[str, int]) -> str:
    if summary.get("total", 0) == 0:
        return "empty"
    return "failed" if summary.get("failed", 0) or summary.get("error", 0) else "passed"


STATUS_LABEL = {"passed": "Passed", "failed": "Failed", "skipped": "Skipped", "error": "Error", "empty": "No tests"}
STATUS_ICON = {"passed": "check-circle", "failed": "cross-circle", "skipped": "minus", "error": "alert-triangle", "empty": "minus"}


def pill(status: str, text: Optional[str] = None) -> str:
    s = status if status in STATUS_LABEL else "skipped"
    return f'<span class="pill pill-{s}">{icon(STATUS_ICON[s])}{esc(text or STATUS_LABEL[s])}</span>'


# ------------------------------------------------------------------ loading

def _empty_run(kind: str, title: str) -> Dict[str, Any]:
    return {"kind": kind, "title": title, "created": None, "duration": None, "exitcode": None,
            "summary": {"total": 0, "passed": 0, "failed": 0, "skipped": 0, "error": 0},
            "tests": [], "environment": {}, "sections": [], "unit_word": "tests", "group_word": "Module"}


def _norm_outcome(outcome: str) -> str:
    o = (outcome or "").lower()
    if o in ("passed", "xpassed"):
        return "passed"
    if o in ("failed",):
        return "failed"
    if o in ("error", "errors"):
        return "error"
    return "skipped"


def load_pytest(path: str, kind: str, title: str) -> Dict[str, Any]:
    """pytest --json-report output."""
    with open(path, encoding="utf-8") as fh:
        data = json.load(fh)
    run = _empty_run(kind, title)
    run["created"] = data.get("created")
    run["duration"] = data.get("duration")
    run["exitcode"] = data.get("exitcode")
    run["environment"] = {k: v for k, v in (data.get("environment") or {}).items() if isinstance(v, (str, int, float))}
    if data.get("root"):
        run["environment"]["Root"] = data["root"]
    for t in data.get("tests") or []:
        nodeid = t.get("nodeid", "")
        parts = nodeid.split("::")
        module = os.path.basename(parts[0])[:-3] if parts and parts[0].endswith(".py") else (parts[0] if parts else "")
        name = parts[-1] if len(parts) > 1 else nodeid
        group = parts[1] if len(parts) > 2 else ""
        dur = sum(float((t.get(stage) or {}).get("duration") or 0) for stage in ("setup", "call", "teardown"))
        message, detail = "", ""
        for stage in ("call", "setup", "teardown"):
            st = t.get(stage) or {}
            if st.get("outcome") in ("failed", "error") or st.get("longrepr"):
                message = (st.get("crash") or {}).get("message") or message
                detail = st.get("longrepr") or detail
                if message or detail:
                    break
        outcome = _norm_outcome(t.get("outcome", ""))
        if outcome == "skipped" and not message:
            lr = (t.get("setup") or {}).get("longrepr") or (t.get("call") or {}).get("longrepr") or ""
            message = str(lr)[:300]
        run["tests"].append({"id": nodeid, "module": module, "group": group, "name": name, "outcome": outcome,
                             "duration": dur, "message": str(message or ""), "detail": str(detail or ""), "steps": []})
    _count(run)
    declared = data.get("summary") or {}
    if not run["tests"] and declared:
        run["summary"].update({k: int(declared.get(k, 0)) for k in ("total", "passed", "failed", "skipped", "error")})
    return run


def load_behave(path: str, kind: str, title: str) -> Dict[str, Any]:
    """behave -f json output: features → scenarios → steps."""
    with open(path, encoding="utf-8") as fh:
        data = json.load(fh)
    run = _empty_run(kind, title)
    run["unit_word"], run["group_word"] = "scenarios", "Feature"
    try:
        run["created"] = os.path.getmtime(path)
    except OSError:
        pass
    total = 0.0
    for feature in data if isinstance(data, list) else []:
        for el in feature.get("elements") or []:
            if el.get("type") == "background":
                continue
            steps, dur, message, detail = [], 0.0, "", ""
            for st in el.get("steps") or []:
                res = st.get("result") or {}
                sd = float(res.get("duration") or 0)
                dur += sd
                s_out = _norm_outcome(res.get("status", "skipped")) if res else "skipped"
                err = res.get("error_message")
                if isinstance(err, list):
                    err = "\n".join(str(x) for x in err)
                if err and not detail:
                    detail = str(err)
                    message = detail.strip().splitlines()[-1][:300] if detail.strip() else ""
                steps.append({"keyword": (st.get("keyword") or "").strip(), "name": st.get("name", ""), "outcome": s_out, "duration": sd})
            total += dur
            status = (el.get("status") or "").lower()
            outcome = _norm_outcome(status if status in ("passed", "failed", "skipped", "error") else
                                    ("failed" if any(s["outcome"] == "failed" for s in steps) else "passed" if steps else "skipped"))
            run["tests"].append({"id": f'{feature.get("name", "")}::{el.get("name", "")}', "module": feature.get("name", ""),
                                 "group": ", ".join(el.get("tags") or []), "name": el.get("name", ""), "outcome": outcome,
                                 "duration": dur, "message": message, "detail": detail, "steps": steps})
    run["duration"] = total
    _count(run)
    return run


def _count(run: Dict[str, Any]) -> None:
    s = {"total": len(run["tests"]), "passed": 0, "failed": 0, "skipped": 0, "error": 0}
    for t in run["tests"]:
        s[t["outcome"]] += 1
    run["summary"] = s


def attach_endurance(run: Dict[str, Any], path: str) -> None:
    """Add the endurance summary (performance, health, configuration) as extra sections."""
    try:
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return
    titles = {"performance": "Performance", "health": "System health", "config": "Run configuration", "test_info": "Test information", "summary": "Load summary"}
    for key in ("summary", "performance", "health", "config", "test_info"):
        block = data.get(key)
        if isinstance(block, dict) and block:
            rows = [(k, v) for k, v in block.items() if isinstance(v, (str, int, float, bool)) or v is None]
            if rows:
                run["sections"].append({"title": titles[key], "rows": rows})


def load_run(kind: str, path: str, title: Optional[str] = None) -> Dict[str, Any]:
    title = title or KINDS.get(kind, {}).get("label", kind.title())
    with open(path, encoding="utf-8") as fh:
        head = fh.read(256).lstrip()[:1]
    if head == "[":
        return load_behave(path, kind, title)
    with open(path, encoding="utf-8") as fh:
        data = json.load(fh)
    if isinstance(data, dict) and "tests" not in data and ("test_info" in data or "performance" in data):
        return load_endurance_summary(path, kind, title)
    return load_pytest(path, kind, title)


def load_endurance_summary(path: str, kind: str, title: str) -> Dict[str, Any]:
    """The endurance summary on its own (no per-test list). Uses the pytest file beside it when there is one."""
    folder, name = os.path.split(path)
    for sibling in ("endurance.json", name.replace("_endurance", "")):
        cand = os.path.join(folder, sibling)
        if sibling != name and os.path.isfile(cand):
            try:
                run = load_pytest(cand, kind, title)
                if run["tests"]:
                    attach_endurance(run, path)
                    return run
            except (OSError, ValueError):
                pass
    with open(path, encoding="utf-8") as fh:
        data = json.load(fh)
    run = _empty_run(kind, title)
    sm = data.get("summary") or {}
    failed = int(sm.get("failed", 0) or 0)
    errors = int(sm.get("errors", 0) or 0)
    passed = int(sm.get("passed", 0) or 0)
    run["summary"] = {"total": int(sm.get("total_tests", passed + failed + errors) or 0), "passed": passed, "failed": failed, "skipped": 0, "error": errors}
    info = data.get("test_info") or {}
    run["duration"] = info.get("duration_seconds") or info.get("duration")
    try:
        run["created"] = os.path.getmtime(path)
    except OSError:
        pass
    for i, f in enumerate(data.get("failures") or []):
        if isinstance(f, dict):
            run["tests"].append({"id": str(f.get("test") or f.get("name") or f"failure {i + 1}"), "module": "endurance", "group": "", "name": str(f.get("test") or f.get("name") or f"failure {i + 1}"),
                                 "outcome": "failed", "duration": 0.0, "message": str(f.get("error") or f.get("message") or ""), "detail": json.dumps(f, indent=2, default=str), "steps": []})
    attach_endurance(run, path)
    return run


