# ------------------------------------------------------------------- shell

def page(title: str, crumbs: List[tuple], hero: str, body: str, generated: Optional[str] = None) -> str:
    trail = []
    for i, (label, href) in enumerate(crumbs):
        if i:
            trail.append(icon("chevron-right"))
        trail.append(f'<a href="{esc(href)}">{esc(label)}</a>' if href else f"<b>{esc(label)}</b>")
    home = crumbs[0][1] if crumbs and crumbs[0][1] else "#"
    stamp = generated or datetime.now(timezone.utc).strftime("%d %b %Y, %H:%M UTC")
    return f"""<!DOCTYPE html>
<html lang="en" data-theme="light">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{esc(title)} · Nexus AI</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600&family=Geist+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>:root{{--hero-img:url({HEADER_IMAGE})}}{CSS}</style>
</head>
<body>
<header class="top"><div class="wrap">
  <a class="brand" href="{esc(home)}" aria-label="Nexus AI test reports">{LOGO}<span>Nexus<em>AI</em></span></a>
  <nav class="crumbs" aria-label="Breadcrumb">{''.join(trail)}</nav>
  <span class="grow"></span>
  <button class="btn no-print" id="print" type="button">{icon('download')}Save as PDF</button>
  <button class="btn btn-icon no-print" id="theme" type="button" aria-label="Switch theme"><span class="sun" style="display:none">{icon('sun')}</span><span class="moon">{icon('moon')}</span></button>
</div></header>
{hero}
<main><div class="wrap">{body}</div></main>
<footer><div class="wrap"><span>Nexus AI · Test reports</span><span>Generated {esc(stamp)} · report kit {KIT_VERSION}</span></div></footer>
<script>{JS}</script>
</body>
</html>
"""


def hero(eyebrow: str, title: str, text: str, icon_name: str, status_html: str = "", meta: Optional[List[tuple]] = None) -> str:
    meta_html = ""
    if meta:
        meta_html = '<dl class="meta">' + "".join(f"<div><dt>{esc(k)}</dt><dd class=\"num\">{esc(v)}</dd></div>" for k, v in meta) + "</dl>"
    return f"""<div class="hero"><div class="wrap">
  <div class="hero-row">
    <span class="hero-ico">{icon(icon_name)}</span>
    <div style="flex:1;min-width:240px"><div class="eyebrow">{esc(eyebrow)}</div><h1>{esc(title)}</h1><p>{esc(text)}</p></div>
    {status_html}
  </div>
  {meta_html}
</div></div>"""


def ring(value: float, status: str) -> str:
    r, c = 37.0, 2 * 3.14159265 * 37.0
    colour = "var(--success)" if status == "passed" else "var(--danger)" if status == "failed" else "var(--c3)"
    off = c * (1 - max(0.0, min(100.0, value)) / 100.0)
    return (f'<svg class="ring" viewBox="0 0 92 92" role="img" aria-label="Pass rate {fmt_pct(value)}">'
            f'<circle class="track" cx="46" cy="46" r="{r}"/>'
            f'<circle class="arc" cx="46" cy="46" r="{r}" stroke="{colour}" stroke-dasharray="{c:.2f}" stroke-dashoffset="{off:.2f}"/>'
            f'<text x="46" y="46">{fmt_pct(value)}</text></svg>')


def kpi_strip(s: Dict[str, int], duration: Optional[float], unit_word: str) -> str:
    rate = pct(s["passed"], s["total"] - s["skipped"]) if s["total"] - s["skipped"] > 0 else 0.0
    st = status_of(s)
    bad = s["failed"] + s["error"]
    verdict = "Every check passed." if st == "passed" else "No tests were run." if st == "empty" else f"{bad} need attention."
    return f"""<div class="kpis fade">
  <div class="card kpi"><div class="rate">{ring(rate, st)}<div><div class="lab">Pass rate</div><div class="val num">{fmt_pct(rate)}</div><div class="sub">{esc(verdict)}</div></div></div></div>
  <div class="card kpi"><div class="lab">{icon('list')}Total {esc(unit_word)}</div><div class="val num">{s['total']}</div><div class="sub">in this run</div></div>
  <div class="card kpi ok"><div class="lab">{icon('check-circle')}Passed</div><div class="val num">{s['passed']}</div><div class="sub">{fmt_pct(pct(s['passed'], s['total']))} of all</div></div>
  <div class="card kpi {'bad' if bad else ''}"><div class="lab">{icon('cross-circle')}Failed</div><div class="val num">{bad}</div><div class="sub">{s['skipped']} skipped</div></div>
  <div class="card kpi"><div class="lab">{icon('clock')}Duration</div><div class="val num" style="font-size:22px;padding-top:5px">{esc(fmt_duration(duration))}</div><div class="sub">total run time</div></div>
</div>"""


# ------------------------------------------------------------------ report

def render_report(run: Dict[str, Any], component: str = "", home: Optional[str] = None, portal: Optional[str] = None) -> str:
    kind = KINDS.get(run["kind"], {"label": run["title"], "icon": "document", "about": ""})
    s, tests = run["summary"], run["tests"]
    st = status_of(s)
    unit, group_word = run.get("unit_word", "tests"), run.get("group_word", "Module")

    # by module
    modules: Dict[str, Dict[str, Any]] = {}
    for t in tests:
        m = modules.setdefault(t["module"] or "(none)", {"passed": 0, "failed": 0, "skipped": 0, "error": 0, "n": 0, "time": 0.0})
        m[t["outcome"]] += 1
        m["n"] += 1
        m["time"] += t["duration"]
    mod_rows = sorted(modules.items(), key=lambda kv: (-kv[1]["failed"] - kv[1]["error"], -kv[1]["n"], kv[0]))[:12]
    top_n = max([m["n"] for _, m in mod_rows] or [1])
    mod_html = "".join(
        f'<div class="bar-row"><span class="name" title="{esc(name)}">{esc(name)}</span>'
        f'<span class="track" style="width:{max(6, 100 * m["n"] / top_n):.0f}%">'
        + "".join(f'<i class="seg-{k}" style="width:{100 * m[k] / m["n"]:.2f}%"></i>' for k in ("passed", "failed", "error", "skipped") if m[k])
        + f'</span><span class="count num">{m["passed"]} / {m["n"]}</span></div>'
        for name, m in mod_rows) or f'<div class="empty">No {esc(unit)} in this run.</div>'

    slow = sorted(tests, key=lambda t: -t["duration"])[:8]
    top_t = max([t["duration"] for t in slow] or [0]) or 1.0
    slow_html = "".join(
        f'<div class="bar-row"><span class="name mono" title="{esc(t["id"])}">{esc(t["name"])}</span>'
        f'<span class="track"><i class="seg-time" style="width:{max(2, 100 * t["duration"] / top_t):.1f}%"></i></span>'
        f'<span class="count num">{esc(fmt_duration(t["duration"]))}</span></div>'
        for t in slow if t["duration"] > 0) or '<div class="empty">No timing was recorded for this run.</div>'

    # table
    rows = []
    for t in sorted(tests, key=lambda t: ({"failed": 0, "error": 1, "skipped": 2, "passed": 3}[t["outcome"]], t["module"], t["name"])):
        more = ""
        if t["steps"]:
            more += '<h4>Steps</h4><ul class="steps">' + "".join(
                f'<li><span class="dot dot-{esc(sx["outcome"])}"></span><span class="kw">{esc(sx["keyword"])}</span><span>{esc(sx["name"])}</span><span class="dur num">{esc(fmt_duration(sx["duration"]))}</span></li>'
                for sx in t["steps"]) + "</ul>"
        if t["message"] and t["outcome"] != "passed":
            more += f'<h4 style="margin-top:10px">Reason</h4><pre>{esc(t["message"])}</pre>'
        if t["detail"]:
            more += f'<h4 style="margin-top:10px">Details</h4><pre>{esc(t["detail"])}</pre>'
        has = bool(more)
        rows.append(
            f'<tr class="row{" has-more" if has else ""}" data-s="{esc(t["outcome"])}" data-t="{esc((t["id"] + " " + t["module"]).lower())}"'
            + (' tabindex="0" aria-expanded="false"' if has else "") + ">"
            f'<td style="width:28px;padding-right:0">{"<span class=chev>" + icon("chevron-right") + "</span>" if has else ""}</td>'
            f'<td><div class="tname">{esc(t["name"])}</div>{"<div class=tgroup>" + esc(t["group"]) + "</div>" if t["group"] else ""}</td>'
            f'<td>{esc(t["module"])}</td><td>{pill(t["outcome"])}</td><td class="num">{esc(fmt_duration(t["duration"]))}</td></tr>'
            + (f'<tr class="more" style="display:none"><td colspan="5"><div class="more-in">{more}</div></td></tr>' if has else ""))
    bad = s["failed"] + s["error"]
    table = f"""<div class="card">
  <div class="tools">
    <label class="search">{icon('search')}<input id="q" type="search" placeholder="Search {esc(unit)}" aria-label="Search {esc(unit)}"></label>
    <div class="chips" role="group" aria-label="Filter by result">
      <button class="chip" data-f="all" aria-pressed="true" type="button">All <b class="num">{s['total']}</b></button>
      <button class="chip" data-f="passed" aria-pressed="false" type="button">Passed <b class="num">{s['passed']}</b></button>
      <button class="chip" data-f="failed" aria-pressed="false" type="button">Failed <b class="num">{s['failed']}</b></button>
      {f'<button class="chip" data-f="error" aria-pressed="false" type="button">Errors <b class="num">{s["error"]}</b></button>' if s['error'] else ''}
      <button class="chip" data-f="skipped" aria-pressed="false" type="button">Skipped <b class="num">{s['skipped']}</b></button>
    </div>
    <span class="count-note num" id="shown">{s['total']} shown</span>
  </div>
  <div class="tbl-wrap"><table>
    <thead><tr><th></th><th>{esc(unit[:-1].title() if unit.endswith('s') else unit.title())}</th><th>{esc(group_word)}</th><th>Result</th><th class="num">Duration</th></tr></thead>
    <tbody>{''.join(rows)}</tbody>
  </table></div>
  <div class="empty" id="none" style="display:{'none' if rows else ''}">{icon('search')}<div>No {esc(unit)} match.</div></div>
</div>"""

    failed = [t for t in tests if t["outcome"] in ("failed", "error")]
    if failed:
        fail_html = "".join(
            f'<div class="card pad fail-card"><h3>{esc(t["id"])}</h3>'
            f'<p class="why">{esc(t["message"] or "No message was recorded.")}</p>'
            + (f'<pre>{esc(t["detail"])}</pre>' if t["detail"] else "") + "</div>" for t in failed)
    else:
        fail_html = f'<div class="card pad"><div class="allgood">{icon("check-circle")}<div><b>No failures</b><br><span>Nothing in this run needs attention.</span></div></div></div>'

    extra = ""
    for sec in run.get("sections") or []:
        kv = "".join(f"<div><dt>{esc(str(k).replace('_', ' ').capitalize())}</dt><dd class=\"num\">{esc(_fmt_value(v))}</dd></div>" for k, v in sec["rows"])
        extra += f'<section><div class="sec-head"><h2>{esc(sec["title"])}</h2></div><div class="card pad"><dl class="kv">{kv}</dl></div></section>'

    env = dict(run.get("environment") or {})
    details = [("Component", component or "—"), ("Test type", kind["label"]), ("Started", fmt_when(run["created"])),
               ("Duration", fmt_duration(run["duration"])), ("Exit code", "—" if run["exitcode"] is None else run["exitcode"]),
               (group_word + "s", len(modules))] + [(k, v) for k, v in env.items()]
    details_html = "".join(f"<div><dt>{esc(k)}</dt><dd>{esc(v)}</dd></div>" for k, v in details)

    body = f"""{kpi_strip(s, run['duration'], unit)}
<section class="grid g2">
  <div class="card pad fade"><div class="sec-head"><h2>Results by {esc(group_word.lower())}</h2><p>Passed out of total</p></div><div class="bars">{mod_html}</div>
    <div class="legend"><span><i class="seg-passed"></i>Passed</span><span><i class="seg-failed"></i>Failed</span><span><i class="seg-skipped"></i>Skipped</span></div></div>
  <div class="card pad fade"><div class="sec-head"><h2>Slowest {esc(unit)}</h2><p>Where the time went</p></div><div class="bars">{slow_html}</div></div>
</section>
<section><div class="sec-head"><h2>Failures</h2><p>{bad} of {s['total']} {esc(unit)}</p></div>{fail_html}</section>
<section><div class="sec-head"><h2>All {esc(unit)}</h2><p>Select a row with an arrow to see its details.</p></div>{table}</section>
{extra}
<section><div class="sec-head"><h2>Run details</h2><p>Where and how this run was produced</p></div><div class="card pad"><dl class="kv">{details_html}</dl></div></section>"""

    crumbs = [("Test reports", portal)] if portal else []
    crumbs += [(component or "Component", home), (kind["label"], None)]
    h = hero(f"{component} · Test report" if component else "Test report", f"{kind['label']} report", kind["about"], kind["icon"],
             pill(st), [("Generated", fmt_when(run["created"])), ("Duration", fmt_duration(run["duration"])),
                        (unit.capitalize(), s["total"]), ("Pass rate", fmt_pct(pct(s["passed"], s["total"] - s["skipped"]) if s["total"] - s["skipped"] > 0 else 0.0))])
    return page(f"{kind['label']} report" + (f" · {component}" if component else ""), crumbs, h, body, fmt_when(run["created"]) if run["created"] else None)


def _fmt_value(v: Any) -> str:
    if isinstance(v, bool):
        return "Yes" if v else "No"
    if isinstance(v, float):
        return f"{v:,.2f}"
    if isinstance(v, int):
        return f"{v:,}"
    return "—" if v is None else str(v)


# --------------------------------------------------------------- dashboard

def summarise(run: Dict[str, Any], href: str) -> Dict[str, Any]:
    return {"kind": run["kind"], "href": href, "created": run["created"], "duration": run["duration"], **run["summary"]}


def render_dashboard(component: str, entries: List[Dict[str, Any]], portal: Optional[str] = None, about: str = "") -> str:
    tot = {k: sum(int(e.get(k, 0)) for e in entries) for k in ("total", "passed", "failed", "skipped", "error")}
    duration = sum(float(e.get("duration") or 0) for e in entries)
    latest = max([e.get("created") or 0 for e in entries] or [0])
    cards = []
    for e in entries:
        k = KINDS.get(e["kind"], {"label": e["kind"].title(), "icon": "document", "about": ""})
        st = status_of(e)
        bad = int(e.get("failed", 0)) + int(e.get("error", 0))
        ran = e["total"] - e["skipped"]
        rate = pct(e["passed"], ran) if ran > 0 else 0.0
        cards.append(f"""<a class="card card-link fade" href="{esc(e['href'])}">
  <div class="card-top"><span class="tile">{icon(k['icon'])}</span><div><h3>{esc(k['label'])}</h3><p>{esc(k['about'])}</p></div>{pill(st)}</div>
  <dl class="stats"><div><dt>Total</dt><dd class="num">{e['total']}</dd></div><div><dt>Passed</dt><dd class="num ok">{e['passed']}</dd></div><div><dt>Failed</dt><dd class="num {'bad' if bad else ''}">{bad}</dd></div><div><dt>Pass rate</dt><dd class="num">{fmt_pct(rate)}</dd></div></dl>
  <span class="track"><i class="seg-passed" style="width:{pct(e['passed'], e['total']):.2f}%"></i><i class="seg-failed" style="width:{pct(bad, e['total']):.2f}%"></i><i class="seg-skipped" style="width:{pct(e['skipped'], e['total']):.2f}%"></i></span>
  <div class="card-foot">{icon('clock')}<span class="num">{esc(fmt_duration(e.get('duration')))}</span><span>·</span><span>{esc(fmt_when(e.get('created')))}</span><span class="go">View report {icon('arrow-right')}</span></div>
</a>""")
    grid = f'<div class="grid g2">{"".join(cards)}</div>' if cards else '<div class="card empty">No reports have been published for this component yet.</div>'
    body = f"""{kpi_strip(tot, duration, 'tests')}
<section><div class="sec-head"><h2>Test types</h2><p>Open one to see every test, its timing and any failure details.</p></div>{grid}</section>"""
    st = status_of(tot)
    h = hero("Test reports", component, about or "Latest results for every type of test in this component.", "dashboard", pill(st),
             [("Last run", fmt_when(latest)), ("Test types", len(entries)), ("Tests", tot["total"]), ("Total time", fmt_duration(duration))])
    crumbs = ([("Test reports", portal)] if portal else []) + [(component, None)]
    return page(f"{component} test reports", crumbs, h, body, fmt_when(latest) if latest else None)


# ------------------------------------------------------------------ portal

def render_portal(components: List[Dict[str, Any]]) -> str:
    """components: [{slug, label, icon, about, href, summary or None}]"""
    live = [c for c in components if c.get("summary")]
    tot = {k: sum(int(c["summary"].get(k, 0)) for c in live) for k in ("total", "passed", "failed", "skipped", "error")}
    duration = sum(float(c["summary"].get("duration") or 0) for c in live)
    latest = max([c["summary"].get("created") or 0 for c in live] or [0])
    cards = []
    for c in components:
        s = c.get("summary")
        if not s:
            cards.append(f"""<div class="card card-link card-off fade" id="{esc(c['slug'])}">
  <div class="card-top"><span class="tile">{icon(c['icon'])}</span><div><h3>{esc(c['label'])}</h3><p>{esc(c['about'])}</p></div>{pill('empty', 'Not published')}</div>
  <p style="margin:0;color:var(--muted-fg);font-size:13px">No reports have been published for this component yet. They appear here after its next test run.</p>
</div>""")
            continue
        st = status_of(s)
        bad = int(s.get("failed", 0)) + int(s.get("error", 0))
        ran = s["total"] - s["skipped"]
        cards.append(f"""<a class="card card-link fade" id="{esc(c['slug'])}" href="{esc(c['href'])}">
  <div class="card-top"><span class="tile">{icon(c['icon'])}</span><div><h3>{esc(c['label'])}</h3><p>{esc(c['about'])}</p></div>{pill(st)}</div>
  <dl class="stats"><div><dt>Tests</dt><dd class="num">{s['total']}</dd></div><div><dt>Passed</dt><dd class="num ok">{s['passed']}</dd></div><div><dt>Failed</dt><dd class="num {'bad' if bad else ''}">{bad}</dd></div><div><dt>Pass rate</dt><dd class="num">{fmt_pct(pct(s['passed'], ran) if ran > 0 else 0.0)}</dd></div></dl>
  <span class="track"><i class="seg-passed" style="width:{pct(s['passed'], s['total']):.2f}%"></i><i class="seg-failed" style="width:{pct(bad, s['total']):.2f}%"></i><i class="seg-skipped" style="width:{pct(s['skipped'], s['total']):.2f}%"></i></span>
  <div class="card-foot">{icon('layers')}<span class="num">{int(s.get('kinds', 0))} test types</span><span>·</span><span>{esc(fmt_when(s.get('created')))}</span><span class="go">Open dashboard {icon('arrow-right')}</span></div>
</a>""")
    body = f"""{kpi_strip(tot, duration, 'tests')}
<section><div class="sec-head"><h2>Components</h2><p>Each component publishes its own results after its test run.</p></div><div class="grid g2">{''.join(cards)}</div></section>"""
    h = hero("Nexus platform", "Test reports", "Automated test results for every component of the Nexus platform, in one place.", "shield-check",
             pill(status_of(tot)), [("Last run", fmt_when(latest)), ("Components reporting", f"{len(live)} of {len(components)}"), ("Tests", tot["total"]), ("Total time", fmt_duration(duration))])
    return page("Test reports", [("Test reports", None)], h, body, fmt_when(latest) if latest else None)


# ---------------------------------------------------------------- building

def find_result(reports_dir: str, kind: str) -> Optional[str]:
    for name in (f"{kind}.json", os.path.join(kind, f"{kind}_test_results.json"), os.path.join(kind, "results.json"), os.path.join(kind, f"{kind}.json")):
        p = os.path.join(reports_dir, name)
        if os.path.isfile(p):
            return p
    return None


def build_site(reports_dir: str, out_dir: str, component: str, slug: str, stamp: Optional[str] = None, portal: Optional[str] = "../index.html") -> Dict[str, Any]:
    """Write a component folder: index.html, <kind>/<stamp>/report.html and summary.json."""
    os.makedirs(out_dir, exist_ok=True)
    entries = []
    for kind in KINDS:
        src = find_result(reports_dir, kind)
        if not src:
            continue
        run = load_run(kind, src)
        if kind == "endurance":
            extra = os.path.join(reports_dir, "endurance_endurance.json")
            if os.path.isfile(extra):
                attach_endurance(run, extra)
        when = stamp or (datetime.fromtimestamp(run["created"], tz=timezone.utc).strftime("%Y%m%d_%H%M%S") if run["created"] else "latest")
        rel = f"{kind}/{when}/report.html"
        dest = os.path.join(out_dir, kind, when)
        os.makedirs(dest, exist_ok=True)
        up = "../../"
        with open(os.path.join(dest, "report.html"), "w", encoding="utf-8") as fh:
            fh.write(render_report(run, component, up + "index.html", (up + portal) if portal else None))
        entries.append(summarise(run, rel))
    about = COMPONENTS.get(slug, {}).get("about", "")
    with open(os.path.join(out_dir, "index.html"), "w", encoding="utf-8") as fh:
        fh.write(render_dashboard(component, entries, portal, about))
    summary = {k: sum(int(e.get(k, 0)) for e in entries) for k in ("total", "passed", "failed", "skipped", "error")}
    summary.update({"component": component, "slug": slug, "kinds": len(entries), "duration": sum(float(e.get("duration") or 0) for e in entries),
                    "created": max([e.get("created") or 0 for e in entries] or [0]) or None, "entries": entries})
    with open(os.path.join(out_dir, "summary.json"), "w", encoding="utf-8") as fh:
        json.dump(summary, fh, indent=2)
    return summary


def build_portal(out_dir: str) -> str:
    """Write <out>/index.html from every <out>/<slug>/summary.json that exists."""
    comps = []
    for slug, meta in COMPONENTS.items():
        summary = None
        p = os.path.join(out_dir, slug, "summary.json")
        if os.path.isfile(p):
            with open(p, encoding="utf-8") as fh:
                summary = json.load(fh)
        comps.append({"slug": slug, **meta, "href": f"{slug}/index.html", "summary": summary})
    dest = os.path.join(out_dir, "index.html")
    os.makedirs(out_dir, exist_ok=True)
    with open(dest, "w", encoding="utf-8") as fh:
        fh.write(render_portal(comps))
    return dest


def kind_for(class_name: str, input_path: str, title: str = "") -> str:
    """Work out the test type from the result file name, the title or the generator class."""
    stem = os.path.basename(input_path).lower()
    text = f"{stem} {title.lower()} {class_name.lower()}"
    for kind, words in (("contract", ("contract",)), ("property", ("property",)), ("e2e", ("e2e", "end-to-end", "end to end")),
                        ("journeys", ("journey",)), ("endurance", ("endurance", "soak")), ("bdd", ("bdd", "behave")),
                        ("integration", ("integration",)), ("unit", ("unit",))):
        if any(w in stem for w in words):
            return kind
    for kind, words in (("contract", ("contract",)), ("property", ("property",)), ("e2e", ("e2e", "end-to-end", "end to end")),
                        ("journeys", ("journey",)), ("endurance", ("endurance",)), ("bdd", ("bdd",)),
                        ("integration", ("integration",)), ("unit", ("unit",))):
        if any(w in text for w in words):
            return kind
    return "unit"


def render_file(kind: str, input_path: str, output_path: str, title: Optional[str] = None, component: str = "",
                home: Optional[str] = None, portal: Optional[str] = None, extra: Optional[str] = None) -> bool:
    """Used by the existing report generators: one result file in, one report out."""
    run = load_run(kind, input_path, title)
    if extra and os.path.isfile(extra):
        attach_endurance(run, extra)
    os.makedirs(os.path.dirname(os.path.abspath(output_path)), exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as fh:
        fh.write(render_report(run, component, home, portal))
    return True


def main(argv: Optional[List[str]] = None) -> int:
    ap = argparse.ArgumentParser(description="Nexus branded test reports")
    sub = ap.add_subparsers(dest="cmd", required=True)
    r = sub.add_parser("report", help="one detailed report")
    r.add_argument("--kind", required=True, choices=list(KINDS))
    r.add_argument("--input", required=True)
    r.add_argument("--output", required=True)
    r.add_argument("--component", default="")
    r.add_argument("--title")
    r.add_argument("--home")
    r.add_argument("--portal")
    r.add_argument("--extra", help="endurance summary JSON")
    s = sub.add_parser("site", help="a component's dashboard and all its reports")
    s.add_argument("--reports", required=True, help="folder holding unit.json, integration.json, bdd.json ...")
    s.add_argument("--out", required=True)
    s.add_argument("--component", required=True)
    s.add_argument("--slug", required=True)
    s.add_argument("--stamp", help="folder name for this run, e.g. 20260509_211605")
    s.add_argument("--no-portal", action="store_true", help="the dashboard is the top page (no link up to a portal)")
    p = sub.add_parser("portal", help="the front page listing every component")
    p.add_argument("--out", required=True)
    a = ap.parse_args(argv)
    if a.cmd == "report":
        render_file(a.kind, a.input, a.output, a.title, a.component, a.home, a.portal, a.extra)
        print(f"Report written: {a.output}")
    elif a.cmd == "site":
        summary = build_site(a.reports, a.out, a.component, a.slug, a.stamp, None if a.no_portal else "../index.html")
        print(f"{a.component}: {summary['kinds']} reports, {summary['passed']}/{summary['total']} passed -> {a.out}")
    else:
        print(f"Portal written: {build_portal(a.out)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
